import SwiftUI

// Color.brandPrimary and Color.brandSecondary are defined via asset catalog
// (BrandPrimary.colorset / BrandSecondary.colorset) and auto-generated by Xcode.
// Light: #1f3d32 / #FDFBF7 — Dark: #d8ebe4 / #111f1a

// Additional brand palette tokens (light-mode fixed values).
// brandSecondary (#FDFBF7) = page/screen background
// brandSurface   (#FAFAF5) = card/surface background — hsl(60, 30%, 97%)
// brandBorder    (#C8D8D0) = borders and dividers     — hsl(158, 20%, 85%)
// brandMuted     (#E6E5E0) = muted fills (pills, badges, tracks) — hsl(60, 10%, 90%)
// brandMutedText (#527A6B) = secondary/muted text     — hsl(158, 20%, 40%)
// brandTerracotta (#E37B5F) = secondary accent        — hsl(13, 70%, 63%)
extension Color {
    static let brandSurface   = Color(hex: "FAFAF5")
    static let brandBorder    = Color(hex: "C8D8D0")
    static let brandMuted     = Color(hex: "E6E5E0")
    static let brandMutedText = Color(hex: "527A6B")
    static let brandTerracotta = Color(hex: "E37B5F")
}

// MARK: - Sign-out environment action

private struct SignOutKey: EnvironmentKey {
    static let defaultValue: () -> Void = {}
}

extension EnvironmentValues {
    var signOut: () -> Void {
        get { self[SignOutKey.self] }
        set { self[SignOutKey.self] = newValue }
    }
}

extension Color {
    init(hex: String) {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: hex).scanHexInt64(&int)
        let a, r, g, b: UInt64
        switch hex.count {
        case 3:
            (a, r, g, b) = (255, (int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
        case 6:
            (a, r, g, b) = (255, int >> 16, int >> 8 & 0xFF, int & 0xFF)
        case 8:
            (a, r, g, b) = (int >> 24, int >> 16 & 0xFF, int >> 8 & 0xFF, int & 0xFF)
        default:
            (a, r, g, b) = (255, 0, 0, 0)
        }
        self.init(
            .sRGB,
            red: Double(r) / 255,
            green: Double(g) / 255,
            blue: Double(b) / 255,
            opacity: Double(a) / 255
        )
    }
}
